//
//       ////////////////
//       //------------//
//       //---I2S_TX---//
//       //------------//
//       ////////////////
//
//is the transmitter module that take the sample/ from the DSP and send them to the DAC (CS4344 ) of the PMOD
// It take 2 bus, 1 per word, of 24 bits each and must translate them, on a wire, in a bit secqunce SDOUT following
// the I2S protocol
//
// the clocks are generated by the CS5343 of the ADC
//
// SAMPLING FREQUENCY 48 KHz;
// LRCK = LOW   --->   left channel
// LRCK = HIGH  --->   right channel
//
//



`timescale 10ns/100ps;

module I2S_TX (
   
   //inputs
   input wire                      BCLK,
   input wire                      LRCK,
   input wire signed [23:0]   SAMP_LEFT,
   input wire signed [23:0]  SAMP_RIGHT,
   input wire                     reset,
   //output
   output reg                     SDATA
   
   );
   
   reg [23:0] shift_reg;
   reg           lrck_d;
   
   ///////////////////////////////////
   // logica di controllo (posedge) //
   ///////////////////////////////////
   
   always @(posedge BCLK) begin
   
	  if (reset) begin
	     
		 lrck_d    <=  1'b0;
		 shift_reg <= 24'd0;
		 
	  end// if reset
	  
	  else begin //logic
	     
	     lrck_d <= LRCK;
		 
	     if (lrck_d != LRCK ) begin
		    
		    ////load the sample
		    if (LRCK) begin
		       shift_reg <= SAMP_RIGHT;
		    end//if lrck
		    else begin
		       shift_reg <= SAMP_LEFT;
		    end//else
		    
	     end//if
	     
	     else begin
	        shift_reg <= {shift_reg[22:0], 1'b0};
	     end//else
	     
	  end// else logic
	  
   end//always
   
   
   ////////////////////////////
   // OUTPUT SDATA (negedge) //
   ////////////////////////////
   
   always @(negedge BCLK) begin
      
	  if (reset) begin
	     
	     SDATA <= 1'b0;
		 
	  end //if reset
	  
	  else begin
	     
	     SDATA <= shift_reg[23];
		 
	  end
	  
   end//always
   
   
endmodule